submitOrder.function:
model.submitting = 0
if (model.submitError) return
// The order number FileMaker returns (Place Order sets $$BF_Model.orderId); Confirmed shows it.
if (typeof app !== 'undefined') app.lastOrderId = model.orderId != null ? String(model.orderId) : ''
console.info('[Colliers order] Order confirmed: ' + (model.orderId || '(id from FileMaker)'), model.orderPayload)
// Empty the ordered cards here, not on Confirmed, so opening /confirmed again keeps a draft (Vue confirmSubmit).
// Cards left off shipping were not ordered: they stay in the cart, still off shipping (Vue clearOrderedLines).
var orderedIds = {}
var anyOrdered = false
function markOrdered(id) {
  orderedIds[String(id)] = true
  anyOrdered = true
}
;((model.orderPayload && model.orderPayload.groups) || []).forEach(function (group) {
  ;(group.items || []).forEach(function (item) {
    markOrdered(item.line_ref)
  })
})
if (!anyOrdered && typeof app !== 'undefined' && app.order)
  (app.order.splits || []).forEach(function (split) {
    ;(split.itemIds || []).forEach(markOrdered)
  })
var cartNow = typeof app !== 'undefined' && Array.isArray(app.cart) ? app.cart : []
var kept = anyOrdered
  ? cartNow.filter(function (line) {
      return !orderedIds[String(line.id)]
    })
  : []
if (!kept.length) {
  BF.namedAction('clearCart')
  if (typeof app !== 'undefined') app.order = { splits: [{ id: 1, itemIds: [], locations: [] }] }
} else {
  cartNow.splice.apply(cartNow, [0, cartNow.length].concat(kept))
  app.cart = cartNow
  app.order = {
    splits: [{ id: 1, itemIds: [], locations: [] }],
    detachedIds: kept.map(function (line) {
      return String(line.id)
    }),
  }
  try {
    if (typeof sessionStorage !== 'undefined') {
      sessionStorage.setItem('colliers-tab.cart', JSON.stringify(cartNow))
      sessionStorage.setItem('colliers-tab.order', JSON.stringify(app.order))
    }
  } catch (err) {}
  BF.namedAction('syncCartHeader')
}
BF.namedAction('goConfirmed')
